SET @task_id=208;
SELECT 'SCHEMA' section,TABLE_NAME,COLUMN_NAME FROM information_schema.columns WHERE TABLE_SCHEMA='armada' AND TABLE_NAME IN ('account_state','account_risk','pull_task_pull_call_member_attempt','pull_task_account_action') ORDER BY TABLE_NAME,ORDINAL_POSITION;
SELECT 'PLANNED_BINDING' section,c.id,c.group_execution_id,c.pull_wave_id,c.wave_call_seq,c.puller_group_account_id,c.puller_account_id,c.puller_assignment_seq,c.planned_material_count,c.call_status,(SELECT COUNT(*) FROM pull_task_material_member m WHERE m.pull_call_id=c.id) bound_materials,(SELECT COUNT(*) FROM pull_task_pull_call_member_attempt a WHERE a.pull_call_id=c.id) total_attempts FROM pull_task_pull_call c JOIN pull_task_pull_wave w ON w.id=c.pull_wave_id WHERE c.task_id=@task_id AND w.wave_status=1 AND c.wave_call_seq=w.next_call_seq;
SELECT 'OUTBOX' section,c.group_execution_id,o.protocol_backend,o.status,o.retry_count,COUNT(*) n,ROUND(AVG((o.sent_at-c.submitted_at)/1000),2) avg_publish_seconds,MAX((o.sent_at-c.submitted_at)/1000) max_publish_seconds,LEFT(MAX(o.last_error),200) last_error FROM pull_task_pull_call c LEFT JOIN protocol_command_outbox o ON o.command_id=c.command_id AND o.tenant_id=c.tenant_id WHERE c.task_id=@task_id AND c.command_id IS NOT NULL GROUP BY c.group_execution_id,o.protocol_backend,o.status,o.retry_count;
SELECT 'LAST_CALLS' section,c.id,c.group_execution_id,c.pull_wave_id,c.wave_call_seq,c.puller_account_id,c.call_status,c.planned_material_count,c.command_id,FROM_UNIXTIME(c.submitted_at/1000) submitted_at,FROM_UNIXTIME(c.result_at/1000) result_at FROM pull_task_pull_call c WHERE c.task_id=@task_id AND c.submitted_at IS NOT NULL ORDER BY c.submitted_at DESC LIMIT 24;
SELECT 'ALL_CALL_TIMELINE' section,c.id,c.group_execution_id,c.pull_wave_id,c.puller_account_id,c.planned_material_count,c.call_status,c.command_id,FROM_UNIXTIME(c.submitted_at/1000) submitted_at,FROM_UNIXTIME(c.result_at/1000) result_at FROM pull_task_pull_call c WHERE c.task_id=@task_id AND c.submitted_at IS NOT NULL ORDER BY c.group_execution_id,c.submitted_at;
